function LadderStruggleRankDialog:InitComponent()
    local param1 = CfUtils.GetCfVo(self.component.settingIdParamVo, ParamVo, 13)
    RankNumMax = checkNumber(param1.num)
    -- 修改页面的背景
    local bgNode = self.controller.transform:Find("BgNode/RawImage")
    if isNotNull(bgNode) then
        local AImg = bgNode.gameObject:GetComponent(typeof(RawImageAlterable))
        if isNotNull(AImg) then
            AImg:LoadSprite(self.component.MainBGPath, "", -1)
        end
    end
end

--- 排行榜列表
---@param maxNum any
function LadderStruggleRankDialog:LoopModeFreshRankCellList(maxNum)
    if not self.LoopListView.IsListViewInit then
        self.LoopListView:InitListView(maxNum, Bind(self, self.OnGetItemByIndex))
        self.LoopListView:UpdateDisplayItemCount("Cell")
    else
        GameUtils.ReloadData(self.LoopListView, maxNum)
    end
end

function LadderStruggleRankDialog:OnGetItemByIndex(loopListView, index)
    if index < 0 then
        return nil
    end

    local cell = loopListView:NewListViewItem("Cell")
    local LB_cell = GetLuaBehaviour(cell.gameObject, RankCellLuaPath)
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        LB_cell:Init()
        LB_cell.Env:SetSystem(self.systemName)
        -- 第一页的节点播放延迟出现的动画
        if index + 1 <= loopListView.DisplayItemCount then
            CfUtils.PlayDelayShowAnimation(cell, index)
        end
    end
    local data = self.rankData[index + 1]
    local LT_cell = LB_cell.Env
    -- print("[大乱斗] 排行榜 cell", table.dump(data, nil, 5))
    LT_cell:UpdatePlayerInfo(self:ConvertData(data))

    return cell
end

function LadderStruggleRankDialog:ShowBlank()
    KTool.SetActive(self.RT_MyRankNode, false)
    KTool.SetActive(self.RT_EmptyNode, true)
end

--- 更新显示我自己的排行信息
function LadderStruggleRankDialog:UpdateMyselfCell()
    local data = self:GetMyselfRankInfo()
    -- print("[大乱斗] 排行榜 my cell", table.dump(data, nil, 5))

    local LB_myCell = GetLuaBehaviour(self.RT_MyRankNode.gameObject, RankCellLuaPath)
    LB_myCell.Env:SetSystem(self.systemName)
    LB_myCell.Env:UpdatePlayerInfo(self:ConvertMySelfData(data))
end

--- 构造我自己的rank信息
---@param rank any
function LadderStruggleRankDialog:GetMyselfRankInfo()
    local myselfInfo = LadderStruggleUtils.GetMyselfPlayerInfo(self.component.questId)
    myselfInfo.ranking = self.myRank
    myselfInfo.percentageRank = self.percentageRank
    myselfInfo.isMyself = true

    return myselfInfo
end

--- 获取我的队伍战力
function LadderStruggleRankDialog:GetMyselfCombatValue()
    local cardComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.CardComponent)
    local teamComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.TeamComponent)
    local teams = teamComponent:GetTeamInfoByQuestId(self.component.questId)

    local totalCombatValue = 0
    for i, teamInfo in ipairs(teams) do
        for j, teamDojo in ipairs(teamInfo.cardsInfo) do
            local cardData = cardComponent:GetCardById(teamDojo.refId)
            if not isNull(cardData) then
                totalCombatValue = totalCombatValue + FormulaUtils.GetCardFightingStrengthen(cardData, {}, false)
            end
        end
    end

    return totalCombatValue
end

--- 把服务器数据格式，转换为cell需要的格式
---@param data any
function LadderStruggleRankDialog:ConvertData(data)
    if isNull(data) then
        return
    end
    if not IsNull(data.converted) then
        return data
    end
    if data.team then
        local team = {}

        for index, teamInfo in pairs(data.team) do
            teamInfo.teamTitle = localize("队伍_num_", {_num_ = index})
            team[checkInt(index)] = teamInfo
        end

        data.team = team
    end
    data.converted = 1

    return data
end

--- 把我自己的数据，转换为cell需要的格式
---@param data any
function LadderStruggleRankDialog:ConvertMySelfData(data)
    if isNull(data) then
        return
    end
    for i, teamInfo in ipairs(data.team) do
        teamInfo.teamTitle = localize("队伍_num_", {_num_ = i})
    end
    return data
end

--- 请求排行榜
function LadderStruggleRankDialog:RequestRank()
    local succeed = false
    local operation = GameUtils.Request(self.component.InterfaceRank, {}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        succeed = true
        local jsonData = response.data
        self.rankData = self:RankDictToList(jsonData.rankInfo)
        self.myRank = checkNumber(jsonData.myRanking)
        self.percentageRank = checkNumber(jsonData.percentageRank)
    end)

    while not succeed do
        cs_coroutine.yield_return()
    end

    if not succeed then
        self.rankData = {}
        self.myRank = 101
        self.percentageRank = 10
    end
end

--- 把服务器下发的字典转化为列表
---@param rankDict any
function LadderStruggleRankDialog:RankDictToList(rankDict)
    local rankList = {}
    for rank, rankInfo in pairs(rankDict) do
        rankInfo.rank = rank
        table.insert(rankList, rankInfo)
    end

    table.sort(rankList, function(a,b)
        return a.rank < b.rank
    end)

    return rankList
end

return LadderStruggleRankDialog


